// AUTO-GENERATED from marketing/content-drafts/composer-bios.md — do not hand-edit.
export const BIOS = {"J. S. Bach":"<p>Johann Sebastian Bach (born 31 March 1685 in Eisenach, Germany; died 28 July 1750 in Leipzig) was a German composer of the late Baroque period, widely regarded as one of the greatest composers in the history of Western music. He is especially celebrated for his mastery of counterpoint and his harmonic innovation.</p><p>His best‑known works include the <em>Brandenburg Concertos</em>, <em>The Well‑Tempered Clavier</em>, the <em>Goldberg Variations</em> and the <em>Mass in B minor</em>. On DoReDog you can play <strong>374</strong> of his pieces — the largest collection in the library — in colour‑coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Sebastian_Bach\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Franz Schubert":"<p>Franz Peter Schubert (born 31 January 1797 in Vienna; died 19 November 1828 in Vienna) was an Austrian composer of the late Classical and early Romantic periods. Extraordinarily prolific, he wrote more than 1,000 works in his short life and is remembered above all as a master of the Lied — the German art song.</p><p>His most famous works include the \"Unfinished\" Symphony (No. 8), the \"Great\" Symphony (No. 9), the song \"Erlkönig\" and the String Quintet in C major. DoReDog has <strong>103</strong> Schubert pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Franz_Schubert\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johannes Brahms":"<p>Johannes Brahms (born 7 May 1833 in Hamburg; died 3 April 1897 in Vienna) was a German composer of the mid‑Romantic period. He is remembered for extending the structural principles of Beethoven while upholding traditional musical forms against the modernist currents of his time.</p><p>His notable works include the Symphony No. 1 in C minor, <em>A German Requiem</em>, the <em>Hungarian Dances</em> and the Violin Concerto in D major. You'll find <strong>95</strong> of his pieces on DoReDog. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johannes_Brahms\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Ludwig van Beethoven":"<p>Ludwig van Beethoven (born December 1770 in Bonn; died 26 March 1827 in Vienna) was a German composer whose work drove the transition from the Classical to the Romantic era. He is regarded as one of the greatest composers in the history of Western music, expanding forms such as the symphony, piano sonata and string quartet.</p><p>His best‑known works include the Symphony No. 5, the Symphony No. 9, the \"Moonlight\" Sonata and his opera <em>Fidelio</em>. DoReDog has <strong>70</strong> Beethoven pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Ludwig_van_Beethoven\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","W. A. Mozart":"<p>Wolfgang Amadeus Mozart (born 27 January 1756 in Salzburg; died 5 December 1791 in Vienna, aged 35) was an Austrian composer of the Classical period. Despite his short life he completed more than 800 works and is regarded as one of the greatest composers in Western music.</p><p>His most famous works include the operas <em>The Marriage of Figaro</em>, <em>Don Giovanni</em> and <em>The Magic Flute</em>, and his unfinished <em>Requiem</em>. On DoReDog you can play <strong>65</strong> of his pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Wolfgang_Amadeus_Mozart\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","G. F. Handel":"<p>George Frideric Handel (born 5 March 1685 in Halle; died 14 April 1759 in London) was a German‑born Baroque composer who became a naturalised British subject in 1727. He is celebrated for bringing Italian opera to its highest development and for creating the genre of English oratorio.</p><p>His best‑known works include <em>Messiah</em> (with its \"Hallelujah\" chorus), the <em>Water Music</em>, <em>Music for the Royal Fireworks</em> and <em>Zadok the Priest</em>. DoReDog has <strong>58</strong> Handel pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/George_Frideric_Handel\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Frédéric Chopin":"<p>Frédéric Chopin (born 1 March 1810 in Żelazowa Wola, near Warsaw; died 17 October 1849 in Paris, aged 39) was a Polish composer of the early Romantic period, whose piano technique was without equal in his generation. He wrote almost exclusively for the piano.</p><p>His Nocturnes, Mazurkas, Polonaises and Études remain cornerstones of the piano repertoire. You'll find <strong>52</strong> Chopin pieces on DoReDog, written out in colour‑coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Fr%C3%A9d%C3%A9ric_Chopin\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Robert Schumann":"<p>Robert Schumann (born 8 June 1810 in Zwickau; died 29 July 1856 in Bonn) was a German composer, pianist and music critic whose compositions typify the spirit of the Romantic era in German music.</p><p>His notable works include <em>Carnaval</em>, <em>Kreisleriana</em>, the song cycle <em>Dichterliebe</em> and the Piano Concerto in A minor. DoReDog has <strong>50</strong> Schumann pieces in letter notes — including several from his <em>Album for the Young</em>, written for beginners. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Robert_Schumann\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Erik Satie":"<p>Erik Satie (born 17 May 1866 in Honfleur, Normandy; died 1 July 1925 in Paris) was a French composer of the late 19th and early 20th centuries. He is credited with steering a new generation of French composers toward a leaner, more spare musical style.</p><p>His best‑known works include the three <em>Gymnopédies</em>, the <em>Gnossiennes</em>, the ballet <em>Parade</em> and <em>Socrate</em>. DoReDog has <strong>27</strong> Satie pieces — his slow, hypnotic <em>Gymnopédies</em> are among the most beginner‑friendly in the whole library. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Erik_Satie\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Georges Bizet":"<p>Georges Bizet (born 25 October 1838 in Paris; died 3 June 1875 in Bougival, near Paris) was a French composer of the Romantic era. He is best remembered for his opera <em>Carmen</em>, now one of the most frequently performed operas in the world — though he died just three months after its premiere, before its success.</p><p>His other works include the <em>L'Arlésienne</em> suite, the opera <em>Les pêcheurs de perles</em> and the <em>Symphony in C</em>. DoReDog has <strong>23</strong> Bizet pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Georges_Bizet\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Joseph Haydn":"<p>Franz Joseph Haydn (born 31 March 1732 in Rohrau, Austria; died 31 May 1809 in Vienna) was an Austrian composer of the Classical period, often called the \"Father of the Symphony\" for his central role in developing the symphony, the string quartet and sonata form.</p><p>His best‑known works include the \"Surprise\" Symphony (No. 94), the \"London\" Symphony (No. 104) and the oratorio <em>The Creation</em>. DoReDog has <strong>19</strong> Haydn pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Joseph_Haydn\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Scott Joplin":"<p>Scott Joplin (born around 1868 in Texas — his exact birth date and place are uncertain; died 1 April 1917 in New York City) was an American composer and pianist known as the \"King of Ragtime.\" He composed more than 40 ragtime pieces and helped elevate ragtime to a respected art form.</p><p>His most famous works include the \"Maple Leaf Rag,\" \"The Entertainer\" and the opera <em>Treemonisha</em>. DoReDog has <strong>19</strong> Joplin rags in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Scott_Joplin\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Gabriel Fauré":"<p>Gabriel Urbain Fauré (born 12 May 1845 in Pamiers, France; died 4 November 1924 in Paris) was a French composer whose style bridged the end of Romanticism and the modernism of the early 20th century. He was one of the foremost French composers of his generation.</p><p>His best‑known works include the <em>Pavane</em>, the <em>Requiem</em>, his Nocturnes for piano and the song \"Clair de lune.\" You'll find <strong>16</strong> Fauré pieces on DoReDog. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Gabriel_Faur%C3%A9\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","P. I. Tchaikovsky":"<p>Pyotr Ilyich Tchaikovsky (born 7 May 1840 in Votkinsk, Russia; died 6 November 1893 in Saint Petersburg) was a Russian composer of the Romantic period — the first Russian composer whose music made a lasting impression internationally.</p><p>His most famous works include the ballets <em>Swan Lake</em> and <em>The Nutcracker</em>, the <em>1812 Overture</em> and his First Piano Concerto. DoReDog has <strong>11</strong> Tchaikovsky pieces in letter notes, including several from his <em>Album for the Young</em>. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Pyotr_Ilyich_Tchaikovsky\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Edvard Grieg":"<p>Edvard Hagerup Grieg (born 15 June 1843 in Bergen, Norway; died 4 September 1907 in Bergen) was a Norwegian composer of the Romantic era whose use of Norwegian folk music brought his country's music to international fame.</p><p>His best‑known works include the Piano Concerto in A minor, the <em>Peer Gynt</em> music (including \"Morning Mood\" and \"In the Hall of the Mountain King\"), the <em>Holberg Suite</em> and the <em>Lyric Pieces</em> for piano. DoReDog has <strong>10</strong> Grieg pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Edvard_Grieg\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Claude Debussy":"<p>Claude Debussy (born 22 August 1862 in Saint‑Germain‑en‑Laye, France; died 25 March 1918 in Paris) was a French composer often described as the first Impressionist composer — a label he himself rejected. He developed an innovative harmonic language that broke away from 19th‑century German tradition.</p><p>His best‑known works include <em>Prélude à l'après‑midi d'un faune</em>, <em>La mer</em>, the opera <em>Pelléas et Mélisande</em> and the beloved \"Clair de lune\" from his <em>Suite bergamasque</em>. DoReDog has <strong>8</strong> Debussy pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Claude_Debussy\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Franz Liszt":"<p>Franz Liszt (born 22 October 1811 in Doborján, Kingdom of Hungary — now Raiding, Austria; died 31 July 1886 in Bayreuth) was a Hungarian composer and pianist of the Romantic period, one of the most prolific and influential composers of his era and a pioneer of the symphonic poem.</p><p>His best‑known works include the <em>Hungarian Rhapsodies</em>, <em>Années de pèlerinage</em>, the <em>Transcendental Études</em> and the Piano Sonata in B minor. DoReDog has <strong>8</strong> Liszt pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Franz_Liszt\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Felix Mendelssohn":"<p>Felix Mendelssohn (born 3 February 1809 in Hamburg; died 4 November 1847 in Leipzig) was a German composer of the early Romantic era. He was central to reviving interest in J. S. Bach's music, notably through his 1829 performance of the <em>St Matthew Passion</em>.</p><p>His best‑known works include the String Octet, the incidental music for <em>A Midsummer Night's Dream</em> (including the famous \"Wedding March\") and the <em>Scottish Symphony</em>. DoReDog has <strong>10</strong> Mendelssohn pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Felix_Mendelssohn\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Domenico Scarlatti":"<p>Domenico Scarlatti (born 26 October 1685 in Naples; died 23 July 1757 in Madrid) was an Italian composer of the Baroque period whose work also influenced the emerging Classical style. He is known mainly for his 555 keyboard sonatas.</p><p>Those sonatas — inventive, brilliant and idiomatic to the keyboard — are the body of work for which he is celebrated. DoReDog has <strong>14</strong> Scarlatti pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Domenico_Scarlatti\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Augusta Mary Anne Holmès":"<p>Augusta Mary Anne Holmès (born 16 December 1847 in Paris; died 28 January 1903 in Versailles) was a French Romantic composer, born to Irish parents and naturalised French in 1871. A pioneering woman composer, she wrote four operas — largely inspired by Wagner — as well as substantial orchestral and vocal works.</p><p>Her best‑known works include the opera <em>La Montagne noire</em>, the <em>Ode triomphale</em> and the symphonic poems <em>Irlande</em> and <em>Andromède</em>. With <strong>66</strong> pieces, she has one of the largest collections on DoReDog. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Augusta_Holm%C3%A8s\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Sergei Rachmaninoff":"<p>Sergei Vasilyevich Rachmaninoff (born 1 April 1873 in Semyonovo, Russia; died 28 March 1943 in Beverly Hills, California) was a Russian composer and pianist, one of the last great representatives of Romanticism in Russian classical music and one of the finest pianists of his era.</p><p>His best‑known works include the Piano Concerto No. 2, the Prelude in C‑sharp minor and the <em>Rhapsody on a Theme of Paganini</em>. DoReDog has <strong>10</strong> Rachmaninoff pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Sergei_Rachmaninoff\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Edward Elgar":"<p>Sir Edward Elgar (born 2 June 1857 in Lower Broadheath, near Worcester, England; died 23 February 1934 in Little Malvern) was an English composer of the late Romantic period whose orchestral works entered the international concert repertoire.</p><p>His best‑known works include the <em>Enigma Variations</em>, <em>The Dream of Gerontius</em>, the <em>Pomp and Circumstance Marches</em> and the Violin Concerto. DoReDog has <strong>10</strong> Elgar pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Edward_Elgar\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Josephine Lang":"<p>Josephine Caroline Lang (born 14 March 1815 in Munich; died 2 December 1880 in Tübingen) was a German composer of the Romantic era who specialised in the Lied — the German art song. Both Felix Mendelssohn and Ferdinand Hiller took pains to help her study composition properly and used their connections to get her music published.</p><p>She wrote numerous songs and piano works across more than 40 opus numbers. DoReDog has <strong>41</strong> Lang pieces in letter notes — one of the larger collections in the library. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Josephine_Lang\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johanna Kinkel":"<p>Johanna Kinkel (née Mockel; born 8 July 1810 in Bonn; died 15 November 1858 in London) was a German composer, writer, pedagogue and revolutionary who took an active part in the 1848 revolutionary movement before emigrating to London.</p><p>Her works include the choral <em>Die Vogelkantate</em> (\"The Bird Cantata,\" Op. 1) and the opera <em>Otto der Schütz</em>. DoReDog has <strong>39</strong> Kinkel pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johanna_Kinkel\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Robert Franz":"<p>Robert Franz (born Robert Franz Julius Knauth; 28 June 1815 in Halle; died 24 October 1892 in Halle) was a German composer of the Romantic era who specialised almost entirely in the Lied, writing around 250 songs. His work was admired by Mendelssohn, Liszt and Schumann, and he also edited music by Bach and Handel.</p><p>DoReDog has <strong>37</strong> Robert Franz pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Robert_Franz\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Liza Lehmann":"<p>Liza Lehmann (born Elisabetha Nina Mary Frederica Lehmann; 11 July 1862 in London; died 19 September 1918 in Pinner, Middlesex) was an English composer and singer, recognised as one of England's foremost female song composers at the turn of the 20th century. She served as the first president of the Society of Women Musicians.</p><p>Her best‑known works include the song cycle <em>In a Persian Garden</em>, <em>The Daisy Chain</em> and the song \"There are Fairies at the Bottom of Our Garden.\" DoReDog has <strong>29</strong> Lehmann pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Liza_Lehmann\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Fanny (Mendelssohn) Hensel":"<p>Fanny Hensel (née Mendelssohn; born 14 November 1805 in Hamburg; died 14 May 1847 in Berlin) was a German composer of the early Romantic era and the elder sister of Felix Mendelssohn. She composed prolifically — over 450 works, including more than 125 pieces for solo piano and over 250 Lieder — yet remained largely unpublished in her lifetime because of the social conventions that restricted women's public musical careers.</p><p>DoReDog has <strong>18</strong> of her pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Fanny_Mendelssohn\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Friedrich Burgmüller":"<p>Friedrich Burgmüller (born Johann Friedrich Franz Burgmüller; 4 December 1806 in Regensburg; died 13 February 1874 in Paris) was a German composer of the Romantic era, best known for his three collections of piano études written as teaching pieces.</p><p>His <em>25 Easy and Progressive Studies</em> (Op. 100) are among the most widely used beginner piano pieces ever written. DoReDog has <strong>19</strong> Burgmüller pieces in letter notes — many ideal for early learners. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Friedrich_Burgm%C3%BCller\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Moritz Moszkowski":"<p>Moritz Moszkowski (born 23 August 1854 in Breslau, then Prussia, now Wrocław, Poland; died 4 March 1925 in Paris) was a German‑Polish composer and pianist of the Romantic era, celebrated in his day as a master pianist and a writer of brilliant piano miniatures.</p><p>His best‑known works include the <em>Spanish Dances</em> (Op. 12) and the <em>Études de Virtuosité</em> (Op. 72). DoReDog has <strong>19</strong> Moszkowski pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Moritz_Moszkowski\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Cécile Chaminade":"<p>Cécile Chaminade (born 8 August 1857 in Paris; died 13 April 1944 in Monte Carlo) was a French composer of the Romantic era. In 1913 she became the first female composer to be awarded the Légion d'Honneur.</p><p>Her best‑known works include the <em>Concertino</em> for flute and orchestra — her most popular piece today — and the \"Scarf Dance.\" DoReDog has <strong>16</strong> Chaminade pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/C%C3%A9cile_Chaminade\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Lili Boulanger":"<p>Lili Boulanger (born Marie‑Juliette Boulanger; 21 August 1893 in Paris; died 15 March 1918 in Mézy‑sur‑Seine, aged 24) was a French composer associated with the Symbolist and Impressionist movements. In 1913 she became the first woman to win the Grand Prix de Rome for composition, with her cantata <em>Faust et Hélène</em>.</p><p>Her other works include <em>D'un matin de printemps</em> and the song cycle <em>Clairières dans le ciel</em>. DoReDog has <strong>16</strong> Boulanger pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Lili_Boulanger\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johann Pachelbel":"<p>Johann Pachelbel (baptised September 1653 in Nuremberg; died early March 1706 in Nuremberg) was a German composer of the middle Baroque era. He is remembered above all for the <em>Canon in D</em>, and was historically important for his contributions to the chorale prelude and the fugue.</p><p>DoReDog has <strong>4</strong> Pachelbel pieces in letter notes — including the ever‑popular Canon in D. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Pachelbel\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Antonio Vivaldi":"<p>Antonio Lucio Vivaldi (born 4 March 1678 in Venice; died 28 July 1741 in Vienna) was an Italian composer of the Baroque era who did much to consolidate the solo concerto form. He is best known for <em>The Four Seasons</em>.</p><p>DoReDog has <strong>2</strong> Vivaldi pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Antonio_Vivaldi\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Peter Cornelius":"<p>Peter Cornelius (born Carl August Peter Cornelius; 24 December 1824 in Mainz; died 26 October 1874 in Mainz) was a German composer of the Romantic period. He is best known for his comic opera <em>Der Barbier von Bagdad</em> (\"The Barber of Baghdad\") and for his <em>Weihnachtslieder</em> (Christmas songs), especially \"Die Könige\" (\"The Three Kings\").</p><p>DoReDog has <strong>25</strong> Cornelius pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Peter_Cornelius\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Clara Mathilda Faisst":"<p>Clara Mathilda Faisst (born 22 June 1872 in Karlsruhe; died 22 November 1948 in Karlsruhe) was a German late‑Romantic composer, pianist and writer. She composed over 100 works — including a Violin Sonata, songs with piano and choral pieces — noted for their expressive melody and rich harmony.</p><p>DoReDog has <strong>25</strong> Faisst pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Clara_Faisst\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Corona Schröter":"<p>Corona Schröter (born Corona Elisabeth Wilhelmine Schröter; 14 January 1751 in Guben; died 23 August 1802 in Ilmenau) was a German singer, actress and composer of the Classical era, active in Goethe's circle at Weimar. She created the title role in Goethe's <em>Iphigenie auf Tauris</em> and composed incidental music for his <em>Die Fischerin</em>, and published two collections of Lieder setting texts by Goethe and Schiller.</p><p>DoReDog has <strong>25</strong> Schröter pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Corona_Schr%C3%B6ter\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Pauline Viardot":"<p>Pauline Viardot (born Michelle Ferdinande Pauline García; 18 July 1821 in Paris; died 18 May 1910 in Paris) was a French mezzo‑soprano, composer and teacher of Spanish descent, one of the leading singers of the 19th century. She created the role of Fidès in Meyerbeer's <em>Le prophète</em> and composed several salon operas, including <em>Cendrillon</em>.</p><p>DoReDog has <strong>20</strong> Viardot pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Pauline_Viardot\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Mathilde Kralik":"<p>Mathilde Kralik (born Mathilde Aloisia Kralik von Meyrswalden; 3 December 1857 in Linz; died 8 March 1944 in Vienna) was an Austrian composer whose works were performed at the Musikverein and other major Viennese venues. Her output includes the fairy‑tale opera <em>Blume und Weissblume</em>, a Symphony in F minor, a Violin Concerto and much sacred, chamber and vocal music.</p><p>DoReDog has <strong>17</strong> Kralik pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Mathilde_Kralik\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Charles Villiers Stanford":"<p>Sir Charles Villiers Stanford (born 30 September 1852 in Dublin; died 29 March 1924 in London) was an Anglo‑Irish composer of the late Romantic era. He is remembered as a hugely influential composition teacher at the Royal College of Music — his pupils included Gustav Holst and Ralph Vaughan Williams — as well as for his own church choral works and his <em>Irish Symphony</em> (No. 3).</p><p>DoReDog has <strong>17</strong> Stanford pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Charles_Villiers_Stanford\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Peter Warlock":"<p>Peter Warlock — the pen name of Philip Arnold Heseltine (born 30 October 1894 in London; died 17 December 1930 in London) — was a British composer of the early 20th century, best known for his songs and other vocal music and for the orchestral <em>Capriol Suite</em>. He was also a pioneering early‑music scholar who transcribed hundreds of early English works.</p><p>DoReDog has <strong>19</strong> Warlock pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Peter_Warlock\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Isaac Albéniz":"<p>Isaac Albéniz (born Isaac Manuel Francisco Albéniz y Pascual; 29 May 1860 in Camprodon, Catalonia; died 18 May 1909 in Cambo‑les‑Bains, France) was a Spanish composer of the post‑Romantic era who wove Spanish folk idioms into his piano music. His best‑known works include the suite <em>Iberia</em> and \"Asturias (Leyenda).\"</p><p>DoReDog has <strong>4</strong> Albéniz pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Isaac_Alb%C3%A9niz\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Muzio Clementi":"<p>Muzio Clementi (born 23 January 1752 in Rome; died 10 March 1832 in Evesham, England) was an Italian‑born composer of the Classical period who spent most of his career in England. Sometimes called the \"Father of the Piano,\" he was among the first to write specifically for the piano's capabilities. His best‑known works include the <em>Gradus ad Parnassum</em> studies and the Six Sonatinas, Op. 36.</p><p>DoReDog has <strong>3</strong> Clementi pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Muzio_Clementi\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Hugo Wolf":"<p>Hugo Wolf (born 13 March 1860 in Windischgrätz, then Austria, now Slovenj Gradec, Slovenia; died 22 February 1903 in Vienna) was an Austrian composer of the late Romantic era, especially noted for his art songs (Lieder), to which he brought a concentrated expressive intensity unique in his time.</p><p>His best‑known works include the <em>Mörike‑Lieder</em>, <em>Eichendorff‑Lieder</em> and <em>Goethe‑Lieder</em>, along with the <em>Italian Serenade</em>. DoReDog has <strong>15</strong> Wolf pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Hugo_Wolf\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","John Philip Sousa":"<p>John Philip Sousa (born 6 November 1854 in Washington, D.C.; died 6 March 1932 in Reading, Pennsylvania) was an American composer and conductor of the late Romantic era, known as \"The March King.\"</p><p>His best‑known works include \"The Stars and Stripes Forever,\" \"Semper Fidelis\" and \"The Washington Post.\" DoReDog has <strong>10</strong> Sousa marches in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/John_Philip_Sousa\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Anton Webern":"<p>Anton Webern (born 3 December 1883 in Vienna; died 15 September 1945 in Mittersill, Austria) was an Austrian composer of the 20th century. Together with Arnold Schoenberg and Alban Berg, he formed the core of the Second Viennese School, and is known for his concise atonal and twelve‑tone works.</p><p>DoReDog has <strong>10</strong> Webern pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Anton_Webern\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Alexander Scriabin":"<p>Alexander Nikolayevich Scriabin (born 6 January 1872 in Moscow; died 27 April 1915 in Moscow) was a Russian composer and pianist, widely considered the primary Russian Symbolist composer, who developed a highly dissonant musical language that moved beyond traditional tonality.</p><p>His best‑known works include <em>The Poem of Ecstasy</em>, <em>Prometheus: The Poem of Fire</em> and his ten piano sonatas. DoReDog has <strong>8</strong> Scriabin pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Alexander_Scriabin\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Stephen Foster":"<p>Stephen Collins Foster (born 4 July 1826 in Lawrenceville, Pennsylvania; died 13 January 1864 in New York City) was an American songwriter of the 19th century, known as \"the father of American music\" and the first American to make songwriting a full‑time profession.</p><p>His best‑known songs include \"Oh! Susanna,\" \"Camptown Races\" and \"Beautiful Dreamer.\" DoReDog has <strong>9</strong> Foster pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Stephen_Foster\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Amy Marcy Beach":"<p>Amy Beach (born Amy Marcy Cheney; 5 September 1867 in Henniker, New Hampshire; died 27 December 1944 in New York City) was an American composer and pianist of the Romantic era — the first successful American female composer of large‑scale art music. Her \"Gaelic\" Symphony was the first symphony composed and published by an American woman.</p><p>DoReDog has <strong>9</strong> Beach pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Amy_Beach\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Samuel Coleridge-Taylor":"<p>Samuel Coleridge‑Taylor (born 15 August 1875 in London; died 1 September 1912 in Croydon) was a British composer of the late Romantic era who won international fame with his cantatas based on Longfellow's <em>The Song of Hiawatha</em> — above all <em>Hiawatha's Wedding Feast</em>.</p><p>DoReDog has <strong>8</strong> Coleridge‑Taylor pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Samuel_Coleridge-Taylor\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Ernest Chausson":"<p>Ernest Chausson (born Amédée‑Ernest Chausson; 20 January 1855 in Paris; died 10 June 1899 near Paris) was a French composer of the Romantic era whose music bridged the ripe Romanticism of Franck and the emerging Impressionism of Debussy. His best‑known works include the <em>Poème</em> for violin and orchestra, the opera <em>Le roi Arthus</em> and his Symphony in B‑flat.</p><p>DoReDog has <strong>12</strong> Chausson pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Ernest_Chausson\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","George Butterworth":"<p>George Butterworth (born 12 July 1885 in London; died 5 August 1916 at Pozières, France) was an English composer of the early 20th century, remembered above all for his orchestral idyll <em>The Banks of Green Willow</em> and his settings of A. E. Housman's <em>A Shropshire Lad</em>. He was killed in action during the First World War.</p><p>DoReDog has <strong>12</strong> Butterworth pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/George_Butterworth\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Maria Theresia von Paradis":"<p>Maria Theresia von Paradis (born 15 May 1759; died 1 February 1824) was an Austrian pianist and composer of the Classical era who lost her sight in early childhood. A celebrated performer who toured internationally, she later founded a music school in Vienna, and Mozart is thought to have composed a piano concerto for her.</p><p>DoReDog has <strong>10</strong> Paradis pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Maria_Theresia_von_Paradis\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Marie Jaëll":"<p>Marie Jaëll (born Marie Trautmann; 17 August 1846 in Steinseltz, France; died 4 February 1925 in Paris) was a French composer, pianist and teacher of the Romantic era. She was the first pianist to perform all of Beethoven's piano sonatas in Paris, and developed an influential piano method grounded in the physiology of touch that is still used today.</p><p>DoReDog has <strong>16</strong> Jaëll pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Marie_Ja%C3%ABll\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Jan Ladislav Dussek":"<p>Jan Ladislav Dussek (born 12 February 1760 in Čáslav, Bohemia; died 20 March 1812 in Saint‑Germain‑en‑Laye, France) was a Czech composer and pianist of the Classical period. One of the first piano virtuosos to tour widely across Europe, he was among the most admired pianists before Beethoven's rise, and his forward‑looking piano writing anticipated the Romantic era.</p><p>DoReDog has <strong>13</strong> Dussek pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Jan_Ladislav_Dussek\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Teodoro Cottrau":"<p>Teodoro Cottrau (born 7 December 1827 in Naples; died 30 March 1879 in Naples) was an Italian composer, lyricist and music publisher of the 19th century who did much to preserve and popularise Neapolitan song. He is best known for his 1850 arrangement of \"Santa Lucia.\"</p><p>DoReDog has <strong>14</strong> Cottrau pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Teodoro_Cottrau\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Clémence de Grandval":"<p>Clémence de Grandval (born Marie Félicie Clémence de Reiset; 21 January 1828 in Saint‑Rémy‑des‑Monts; died 15 January 1907 in Paris) was a French composer of the Romantic era. Prolific in opera and instrumental music — with many works for the oboe — she was among the most‑played composers at the Société Nationale de Musique in the 1870s and won the first Prix Rossini in 1881.</p><p>DoReDog has <strong>13</strong> Grandval pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Cl%C3%A9mence_de_Grandval\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Helena Munktell":"<p>Helena Mathilda Munktell (born 24 November 1852 in Grycksbo, Sweden; died 10 September 1919 in Stockholm) was a Swedish post‑Romantic composer of orchestral, vocal and operatic works. She became a member of the Royal Swedish Academy of Music and helped found the Swedish Society of Composers.</p><p>DoReDog has <strong>12</strong> Munktell pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Helena_Munktell\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Arthur Somervell":"<p>Sir Arthur Somervell (born 5 June 1863 in Windermere; died 2 May 1937 in London) was an English composer of the English Musical Renaissance, chiefly remembered for his song cycles — including settings of Tennyson's <em>Maud</em> and Housman's <em>A Shropshire Lad</em> — and as an influential reformer of music education.</p><p>DoReDog has <strong>9</strong> Somervell pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Arthur_Somervell\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Frank Bridge":"<p>Frank Bridge (born 26 February 1879 in Brighton; died 10 January 1941) was an English composer whose style evolved from late Romanticism toward modernism. He is known for the orchestral work <em>The Sea</em> and as the private teacher of Benjamin Britten, who paid tribute in his <em>Variations on a Theme of Frank Bridge</em>.</p><p>DoReDog has <strong>8</strong> Bridge pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Frank_Bridge\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Harry Thacker Burleigh":"<p>Harry Thacker Burleigh (born 2 December 1866 in Erie, Pennsylvania; died 12 September 1949 in Stamford, Connecticut) was an American composer and singer, a pioneering figure who arranged African‑American spirituals in a classical form and made them available to concert artists. He introduced Antonín Dvořák to Black American music.</p><p>DoReDog has <strong>8</strong> Burleigh pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Harry_Burleigh\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Chiquinha Gonzaga":"<p>Chiquinha Gonzaga (born Francisca Edwiges Neves Gonzaga; 17 October 1847 in Rio de Janeiro; died 28 February 1935 in Rio de Janeiro) was a Brazilian composer, pianist and conductor — the first woman conductor in Brazil and the first pianist of choro. She wrote the first Brazilian carnival march and composed roughly 2,000 works.</p><p>DoReDog has <strong>8</strong> Gonzaga pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Chiquinha_Gonzaga\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Alexander Mackenzie":"<p>Sir Alexander Campbell Mackenzie (born 22 August 1847 in Edinburgh; died 28 April 1935 in London) was a Scottish composer of the Romantic era, known for his oratorios, violin and piano pieces and works drawing on Scottish folk music. With Hubert Parry and Charles Villiers Stanford, he is regarded as one of the fathers of the British musical renaissance.</p><p>DoReDog has <strong>8</strong> Mackenzie pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Alexander_Mackenzie_(composer\" target=\"_blank\" rel=\"noopener\">Wikipedia</a>)</em></p>"};
